function handleGlobalKeydown(ev){if(state.hotkeyCaptureCommand){ev.preventDefault();ev.stopPropagation();if(ev.key==='Escape'){state.hotkeyCaptureCommand='';state.hotkeyCaptureAppend=false;renderDockPanelByKey('bottom:hotkeys');return}if(['Backspace','Delete'].includes(ev.key)&&!ev.ctrlKey&&!ev.altKey&&!ev.metaKey){state.project.editor.hotkeys=setHotkeyOverride(ensureHotkeySettings(),state.hotkeyCaptureCommand,[]);state.hotkeyCaptureCommand='';state.hotkeyCaptureAppend=false;persistHotkeys();state.dirty=true;renderDockPanelByKey('bottom:hotkeys');return}const binding=eventToHotkey(ev);if(!binding||['Ctrl','Alt','Shift','Meta'].includes(binding))return;const id=state.hotkeyCaptureCommand,append=Boolean(state.hotkeyCaptureAppend);state.hotkeyCaptureCommand='';state.hotkeyCaptureAppend=false;setCommandBinding(id,binding,{append});return}if(ev.key==='Escape'){$('#modal-layer').innerHTML='';$('#popover-layer').innerHTML='';$$('.toolbar-menu[open]').forEach(x=>x.removeAttribute('open'));return}const tag=document.activeElement?.tagName,editing=['INPUT','TEXTAREA','SELECT'].includes(tag)||document.activeElement?.isContentEditable;if(state.mode==='design'&&!editing&&!$('#modal-layer')?.children.length){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(ev.key)){const d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[ev.key];if(nudgeSelected(d[0],d[1],ev.shiftKey,ev.altKey?1:null)){ev.preventDefault();return}}else if(ev.key==='Delete'||ev.key==='Backspace'){ev.preventDefault();deleteSelected();return}}const hit=commandForEvent(ev,commandDefinitions(),ensureHotkeySettings());if(hit&&shouldHandleHotkey(ev,hit.command)){ev.preventDefault();executeCommand(hit.command.id)}}
function commandPalette(){const commands=commandDefinitions(),map=currentHotkeyMap(),layer=$('#modal-layer');layer.innerHTML=`<div class="modal-backdrop"><div class="modal command-palette"><input data-command-search class="command-search" placeholder="Type a command…"><div data-command-list class="command-list"></div></div></div>`;const input=layer.querySelector('[data-command-search]'),list=layer.querySelector('[data-command-list]');const draw=()=>{const q=input.value.toLowerCase(),items=commands.filter(c=>!q||`${c.label} ${c.category} ${c.id}`.toLowerCase().includes(q)).slice(0,80);list.innerHTML=items.map(c=>`<button class="command-item" data-command-run="${esc(c.id)}"><span><strong>${esc(c.label)}</strong><small>${esc(c.category)}</small></span><kbd>${esc(hotkeyLabel((map[c.id]||[])[0]||'',navigator.platform||''))}</kbd></button>`).join('');list.querySelectorAll('[data-command-run]').forEach(b=>b.onclick=()=>{layer.innerHTML='';executeCommand(b.dataset.commandRun)})};input.oninput=draw;input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();list.querySelector('[data-command-run]')?.click()}if(e.key==='Escape')layer.innerHTML=''};draw();input.focus()}
