function renderIntegrationsPanel(box){const plugins=getDesignerPlugins(),contrib=getDesignerContributions();box.innerHTML=`<div class="workbench-grid"><section class="workbench-card"><strong>Installed plugins</strong>${plugins.map(p=>`<div class="source-row"><span>◆</span><span>${esc(p.name||p.id)}<small>${esc(p.version||p.id)}</small></span></div>`).join('')||'<div class="empty">No plugins installed.</div>'}</section>${Object.entries(contrib).map(([kind,items])=>`<section class="workbench-card"><strong>${esc(kind)} · ${(items||[]).length}</strong>${(items||[]).map(x=>`<button class="provider-btn" data-kind="${esc(kind)}" data-id="${esc(x.id)}">${esc(x.label||x.name||x.id)}</button>`).join('')||'<div class="empty">No providers.</div>'}</section>`).join('')}</div>`;box.querySelectorAll('.provider-btn').forEach(b=>b.onclick=async()=>{const item=(contrib[b.dataset.kind]||[]).find(x=>x.id===b.dataset.id);try{const r=await item?.run?.({project:state.project,node:selected(),selection:[selected()]});log(`${item?.label||item?.id}: ${JSON.stringify(r)}`);if(r?.changed){state.dirty=true;renderAll()}}catch(err){log(`Provider error: ${err.message}`)}})}
function renderRoundtripPanel(box){const rt=state.project.workspace?.roundTrip||{};box.innerHTML=`<div class="workbench-grid"><section class="workbench-card"><strong>Round-trip Studio</strong><p>Review source ↔ design changes, AST mappings, conflicts, history and conversion.</p><div class="inspector-toolbar"><button data-project-import class="primary">Import Existing Project…</button><button data-roundtrip-open>Open Studio</button></div></section><section class="workbench-card"><strong>Round-trip status</strong><div class="meta">Workspace: ${esc(state.project.workspace?.rootPath||'not open')}</div><div>Backend: ${esc(rt.backend||'auto')}</div><div>Dirty state: ${esc(rt.dirtyState||'clean')}</div><div>Source mappings: ${Object.keys(rt.sourceIdentities||{}).length||state.project.workspace?.sourceMappings?.length||0}</div></section></div>`;box.querySelector('[data-project-import]').onclick=importExistingProject;box.querySelector('[data-roundtrip-open]').onclick=()=>window.AstroUIDesignerRoundTrip?.openStudio?.()}

