function dockZoneElements(zone){return {strip:$(`#${zone}-tabs`),content:$(`#${zone}-content`),shell:zone==='bottom'?$('.bottom-dock'):$(`.${zone}-dock`)}}
function dockPanelFromKey(key){return dockState.registry?.[key]||null}
function dockKeyForOriginId(origin,id){return `${origin}:${id}`}
function dockLayoutSnapshot(){return deepClone(dockState.layout||{zones:{left:[],right:[],bottom:[]},active:{left:null,right:null,bottom:null},floating:{}})}
