const DOCK_SIZE_STORAGE_KEY='astro-ui-designer-dock-sizes-v1';
function loadDockSizes(){try{const x=JSON.parse(localStorage.getItem(DOCK_SIZE_STORAGE_KEY)||'{}');if(x.left)document.documentElement.style.setProperty('--left-dock-width',`${x.left}px`);if(x.right)document.documentElement.style.setProperty('--right-dock-width',`${x.right}px`);if(x.bottom)document.documentElement.style.setProperty('--bottom-dock-height',`${x.bottom}px`)}catch{}}
function saveDockSizes(){const cs=getComputedStyle(document.documentElement),v={left:parseFloat(cs.getPropertyValue('--left-dock-width'))||235,right:parseFloat(cs.getPropertyValue('--right-dock-width'))||330,bottom:parseFloat(cs.getPropertyValue('--bottom-dock-height'))||220};try{localStorage.setItem(DOCK_SIZE_STORAGE_KEY,JSON.stringify(v))}catch{}}
function bindDockResizers(){loadDockSizes();for(const [id,kind] of [['left-splitter','left'],['right-splitter','right'],['bottom-splitter','bottom']]){const splitter=$(`#${id}`);if(!splitter)continue;splitter.title='Drag to resize dock · double-click to reset';splitter.onpointerdown=e=>{e.preventDefault();const sx=e.clientX,sy=e.clientY,cs=getComputedStyle(document.documentElement),start=kind==='left'?parseFloat(cs.getPropertyValue('--left-dock-width')):kind==='right'?parseFloat(cs.getPropertyValue('--right-dock-width')):parseFloat(cs.getPropertyValue('--bottom-dock-height'));splitter.classList.add('resizing');const move=ev=>{let value=kind==='left'?start+(ev.clientX-sx):kind==='right'?start-(ev.clientX-sx):start-(ev.clientY-sy);value=Math.max(kind==='bottom'?100:170,Math.min(kind==='bottom'?650:620,value));document.documentElement.style.setProperty(kind==='left'?'--left-dock-width':kind==='right'?'--right-dock-width':'--bottom-dock-height',`${Math.round(value)}px`)};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);splitter.classList.remove('resizing');saveDockSizes()};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up)};splitter.ondblclick=()=>{document.documentElement.style.setProperty(kind==='left'?'--left-dock-width':kind==='right'?'--right-dock-width':'--bottom-dock-height',kind==='left'?'235px':kind==='right'?'330px':'220px');saveDockSizes()}}}
