function showDockLayoutMenu(e){const layer=$('#popover-layer'),r=e.currentTarget?.getBoundingClientRect?.()||{left:e.clientX||100,bottom:e.clientY||60};const x=Math.min(innerWidth-270,Math.max(4,r.left)),y=Math.min(innerHeight-190,Math.max(4,r.bottom+3));layer.innerHTML=`<div class="dock-context-menu dock-help-menu" style="left:${x}px;top:${y}px;width:260px"><strong>Relocatable docks</strong><div class="dock-menu-help">Drag any panel tab between Left, Right and Bottom. Drop outside to float it. Double-click a tab to float. Right-click a tab for exact placement. Floating panels can be moved and resized.</div><button data-dock-reset>Reset default dock layout</button><button data-dock-expand-bottom>${state.bottomExpanded?'Collapse':'Expand'} bottom dock</button></div>`;layer.querySelector('[data-dock-reset]').onclick=()=>{layer.innerHTML='';resetDockLayoutUi()};layer.querySelector('[data-dock-expand-bottom]').onclick=()=>{layer.innerHTML='';state.bottomExpanded=!state.bottomExpanded;$('#app').classList.toggle('bottom-minimized',!state.bottomExpanded);$('#bottom-toggle-btn').textContent=state.bottomExpanded?'⌄':'⌃';renderDockZone('bottom')};setTimeout(()=>document.addEventListener('pointerdown',ev=>{if(!ev.target.closest?.('.dock-context-menu')&&layer.querySelector('.dock-context-menu'))layer.innerHTML=''},{once:true}),0)}
