function bindFloatingWindow(win,key){const header=win.querySelector('.floating-dock-titlebar');header.onpointerdown=e=>{if(e.target.closest('button'))return;e.preventDefault();bringFloatingDockFront(win);const rect=win.getBoundingClientRect(),sx=e.clientX,sy=e.clientY;const move=ev=>{win.style.left=`${Math.max(0,rect.left+ev.clientX-sx)}px`;win.style.top=`${Math.max(30,rect.top+ev.clientY-sy)}px`};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);dockState.layout=updateFloatingRect(dockState.layout,key,{x:parseFloat(win.style.left)||0,y:parseFloat(win.style.top)||30,width:win.offsetWidth,height:win.offsetHeight});persistDockLayout()};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up)};header.ondblclick=e=>{if(!e.target.closest('button'))moveDockPanelUi(key,dockPanelFromKey(key).origin)};win.onpointerdown=()=>bringFloatingDockFront(win);win.onpointerup=()=>{dockState.layout=updateFloatingRect(dockState.layout,key,{x:parseFloat(win.style.left)||0,y:parseFloat(win.style.top)||30,width:win.offsetWidth,height:win.offsetHeight});persistDockLayout()};win.querySelectorAll('[data-float-dock]').forEach(b=>b.onclick=()=>moveDockPanelUi(key,b.dataset.floatDock));win.querySelector('[data-float-home]').onclick=()=>moveDockPanelUi(key,dockPanelFromKey(key).origin)}
function sectionLayoutState(){try{return JSON.parse(localStorage.getItem(SECTION_STORAGE_KEY)||'{}')}catch{return{}}}
function sectionDisclosureState(){try{return JSON.parse(localStorage.getItem(SECTION_DISCLOSURE_STORAGE_KEY)||'{}')}catch{return{}}}
function persistSectionDisclosure(panelKey,id,open){const all=sectionDisclosureState();all[panelKey]??={};all[panelKey][id]=Boolean(open);try{localStorage.setItem(SECTION_DISCLOSURE_STORAGE_KEY,JSON.stringify(all))}catch{}}
function sectionIdentity(el,index){const label=(el.querySelector(':scope > summary,:scope > strong:first-child,:scope > .group-head')?.textContent||el.getAttribute('aria-label')||`section-${index}`).trim().replace(/\s+/g,' ').slice(0,80);return label||`section-${index}`}
function sectionCandidates(host){const direct=[...host.children].filter(x=>x.matches?.('.property-section,.workbench-card'));const nested=[...host.querySelectorAll(':scope > .workbench-grid > .workbench-card')];return [...new Set([...direct,...nested])]}
