function refreshBreakpointControl(){const sel=$('#breakpoint-select');if(!sel)return;const bps=state.project.settings.breakpoints||[];sel.innerHTML=bps.map(b=>`<option value="${b.id}" ${b.id===state.breakpoint?'selected':''}>${esc(b.label)} · ${b.width}</option>`).join('')}

function renderAll(){normalizeProject();ensureHotkeySettings();refreshBreakpointControl();renderDocTabs();renderCanvas();renderDockZones();renderStatus();syncTabs()}
function setMode(mode){if(mode==='simulate'){if(!state.simulationSession)startSimulation();else scheduleSimulationDelays()}if(state.mode==='simulate'&&mode!=='simulate')clearSimulationTimers();state.mode=mode;state.editorView=mode;renderCanvas();syncTabs()}
function saveProject(){const blob=new Blob([JSON.stringify(state.project,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${state.project.name||'astro-ui-project'}.astro-ui.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);state.dirty=false;renderStatus()}
