async function scanWorkspace(){try{const s=await rescanWorkspace();state.project.workspace.files=(s.files||[]).map(workspaceFileRow);state.project.workspace.lastScan=new Date().toISOString();renderDockZones();log(`Workspace scan: ${state.project.workspace.files.length} files`);return s}catch(e){log(`Workspace scan failed: ${e.message}`);throw e}}
